```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;

public class VulnerableExample {
    public static void main(String[] args) {
        String userInput = "1 OR 1=1"; // Simulated user input that could be malicious
        Connection connection = null;
        Statement statement = null;

        try {
            // Establishing connection to the database
            connection = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydatabase", "user", "password");

            // Creating a statement object
            statement = connection.createStatement();

            // Vulnerable: Concatenating user input directly into SQL query
            String query = "SELECT * FROM users WHERE user_id = " + userInput;
            ResultSet resultSet = statement.executeQuery(query);

            // Processing the result set
            while (resultSet.next()) {
                System.out.println("User ID: " + resultSet.getInt("user_id"));
                System.out.println("Username: " + resultSet.getString("username"));
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                if (statement != null) statement.close();
                if (connection != null) connection.close();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}
```

***
```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class SecureExample {
    public static void main(String[] args) {
        String userInput = "1"; // User input should be sanitized and validated
        Connection connection = null;
        PreparedStatement preparedStatement = null;

        try {
            // Establishing connection to the database
            connection = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydatabase", "user", "password");

            // Secure: Using a prepared statement to prevent SQL injection
            String query = "SELECT * FROM users WHERE user_id = ?";
            preparedStatement = connection.prepareStatement(query);
            preparedStatement.setString(1, userInput);
            ResultSet resultSet = preparedStatement.executeQuery();

            // Processing the result set
            while (resultSet.next()) {
                System.out.println("User ID: " + resultSet.getInt("user_id"));
                System.out.println("Username: " + resultSet.getString("username"));
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                if (preparedStatement != null) preparedStatement.close();
                if (connection != null) connection.close();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}
```

In the "VulnerableExample" code snippet, the vulnerability arises from directly concatenating user input into an SQL query, making it susceptible to SQL injection attacks. In the "SecureExample," a `PreparedStatement` is used, which safely handles the user input and prevents SQL injection.

