***
```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class SecureSQL {
    public static void main(String[] args) {
        String userInput = "1"; // Simulated user input
        try {
            Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/testdb", "user", "password");
            // Use PreparedStatement to prevent SQL Injection
            String query = "SELECT * FROM users WHERE id = ?";
            PreparedStatement pstmt = conn.prepareStatement(query);
            pstmt.setString(1, userInput); // Safely set user input
            ResultSet rs = pstmt.executeQuery();
            while (rs.next()) {
                System.out.println("User: " + rs.getString("username"));
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

In the first snippet, the application is vulnerable to SQL injection because it directly concatenates user input into the SQL query. The second snippet fixes this vulnerability by using a `PreparedStatement`, which safely handles user input by parameterizing the SQL query.
